var util = {
  checkWeixinApp: function () {
    if (window.__wxjs_environment === 'miniprogram' || (util.checkWeixin() && /(miniprogram)/.test(navigator.userAgent.toLowerCase()))) {
      return true
    } else {
      return false
    }
  },

  checkLifeApp: function () {
    if ((/(pigcmso2olifeapp)/.test(navigator.userAgent.toLowerCase()) && /(life_app)/.test(navigator.userAgent.toLowerCase())) || /(pigcmso2oreallifeapp)/.test(navigator.userAgent.toLowerCase())) {
      return true
    } else {
      return false
    }
  },

  checkIos: function () {
    if (/(iphone|ipad|ipod)/.test(navigator.userAgent.toLowerCase())) {
      return true
    } else {
      return false
    }
  },

  checkIosApp: function () {
    if (util.checkLifeApp() && util.checkIos()) {
      return true
    } else {
      return false
    }
  },

  checkAndroid: function () {
    if (/(android)/.test(navigator.userAgent.toLowerCase())) {
      return true
    } else {
      return false
    }
  },

  checkWeixin: function () {
    if (/(micromessenger)/.test(navigator.userAgent.toLowerCase())) {
      return true
    } else {
      return false
    }
  },

  appFunction: function (obj) {
    // obj.name 调用app方法名
    if (!obj || !obj.name) {
      console.log('')
      return false
    }
    if (util.checkAndroid()) {
      window.pigcmspackapp[obj.name](JSON.stringify(obj))
    } else {
      window.webkit.messageHandlers.PackAppJSBridgeMethod.postMessage(obj)
    }
  },

  projectName: 'paotui',
  storage: {
    get: function (key) {
      let temp = window.localStorage.getItem(util.projectName + '_' + key)
      if (temp) {
        return JSON.parse(temp)
      } else {
        return false
      }
    },
    set: function (key, value) {
      window.localStorage.setItem(util.projectName + '_' + key, JSON.stringify(value))
    },
    remove: function (key) {
      window.localStorage.removeItem(util.projectName + '_' + key)
    },
    clear: function () {
      window.localStorage.clear()
    }
  },

  // 检查登录
  checkLogin: function () {
    let isLogin = util.storage.get('ticket')
    if (!isLogin) {
      location.href = process.env.VUE_APP_BASE_API + '/packapp/my/login.html?back=' + encodeURIComponent('/packapp/run_errands/index') + '&visit=paotui'
      return false
    } else {
      return true
    }
  }
}

export default util
